import json

# Create commands to add transition elements at the end of pattern 5
batch = []

def note(name):
    if name is None or name == '---':
        return None
    notes = {'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5, 
             'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11}
    if len(name) == 3:
        note_name = name[0]
        octave = int(name[2])
    elif len(name) == 4:
        note_name = name[0:2]
        octave = int(name[3])
    return 1 + notes[note_name] + (octave * 12)

KICK = 1
SNARE = 2
HIHAT_C = 3
ARP = 7

# Add snare roll at end of pattern 5 (rows 56-63)
for row in [48, 52, 54, 56, 57, 58, 59, 60, 61, 62, 63]:
    vol = 32 + (row - 48) * 2  # Building up
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 5,
            "row": row,
            "channel": 1,  # Snare channel
            "note": note('C-5'),
            "instrument": SNARE,
            "volume": min(vol, 60)
        }
    })

# Add kick build up
for row in [48, 52, 56, 58, 60, 62]:
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 5,
            "row": row,
            "channel": 0,
            "note": note('C-5'),
            "instrument": KICK,
            "volume": 56
        }
    })

# Add hi-hat acceleration
for row in range(48, 64):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 5,
            "row": row,
            "channel": 2,
            "note": note('C-5'),
            "instrument": HIHAT_C,
            "volume": 40
        }
    })

# Add arp notes building up
arp_notes = ['A-4', 'C-5', 'E-5']
for row in range(48, 64, 2):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 5,
            "row": row,
            "channel": 4,
            "note": note(arp_notes[(row//2) % 3]),
            "instrument": ARP,
            "volume": 36
        }
    })

with open('/workspace/fix_transition.json', 'w') as f:
    json.dump(batch, f)

print(f"Created {len(batch)} commands for transition fix")
